 const h=CHAOS_HERO_BY_ID[id]||CHAOS_HERO_BY_ID.pudge,col=options.color||h.color,t=options.time||0;c.save();c.translate(Math.round(x),Math.round(y));c.scale(size/40,size/40);c.globalAlpha=options.illusion?.55:1;
 const r=(x,y,w,h,color)=>{c.fillStyle=color;c.fillRect(x,y,w,h);},line=(pts,color,width=2)=>{c.beginPath();c.strokeStyle=color;c.lineWidth=width;pts.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke();};
 c.fillStyle='#050c0980';c.beginPath();c.ellipse(0,17,19,6,0,0,Math.PI*2);c.fill();
