 if(['drow','pa','cm','rubick','invoker'].includes(id)){r(-10,-19,20,8,id==='pa'?'#203942':'#324d49');r(-13,-10,6,24,col);r(8,-10,6,24,col);r(-5,-10,10,4,'#c3d9c2');}
