 if(id==='ogre'){r(-17,-10,34,26,'#6a99b8');r(-14,-22,13,14,'#80b5ce');r(2,-20,14,13,'#7eafc3');r(-11,-18,3,3,'#141c19');r(7,-16,3,3,'#141c19');r(-12,3,24,5,'#856849');line([[15,4],[23,-19]],'#715c41',5);r(18,-23,11,12,'#9a9677');}
 if(id==='tinker'||id==='timber'){r(-18,-1,36,18,'#777c67');r(-13,-13,26,16,id==='tinker'?'#b28d44':'#ad6650');r(-8,-19,16,12,'#bdc6bd');r(-7,-16,5,4,'#6fb6cd');r(2,-16,5,4,'#6fb6cd');r(-21,8,10,9,'#353d32');r(11,8,10,9,'#353d32');if(id==='tinker'){line([[-15,0],[-23,-13],[-26,-13]],'#c3bd83',3);r(15,-4,13,7,'#d6bc6e');r(25,-3,5,4,'#a9e5d6');}else{c.save();c.translate(20,6);c.rotate(t*5);artSaw(c,0,0,13,'#d7d6b7');c.restore();}}
 if(id==='terrorblade'){r(-9,-3,18,21,'#223c3b');line([[-5,-18],[-17,-28],[-14,-14]],col,3);line([[5,-18],[17,-28],[14,-14]],col,3);line([[-9,1],[-24,-9],[-30,10],[-14,8]],'#448b79',4);line([[9,1],[24,-9],[30,10],[14,8]],'#448b79',4);line([[-17,8],[-23,-3]],'#a4f6c6',3);}
 if(id==='sf'){r(-8,-22,16,33,'#542629');r(-15,-4,30,18,'#61282a');r(-4,-15,3,3,'#ffda81');r(3,-15,3,3,'#ffda81');line([[-7,-20],[-17,-29],[-13,-16]],'#dd6554',3);line([[7,-20],[17,-29],[13,-16]],'#dd6554',3);line([[-14,0],[-23,9],[-17,14]],'#da634a',4);line([[14,0],[23,9],[17,14]],'#da634a',4);r(-4,2,8,6,'#ef8b56');}
